import workcell

def parse_status():
    t = workcell.robot("status").text
    lines = t.splitlines()
    out = {}
    for line in lines:
        if line.startswith("left"):
            # TCP at x=-4 y=59 z=200 mm
            parts = line.replace(";", " ").split()
            # find x= y= z=
            d = {}
            for p in parts:
                if p.startswith("x="): d["x"]=float(p[2:])
                if p.startswith("y="): d["y"]=float(p[2:])
                if p.startswith("z="): d["z"]=float(p[2:])
            out["left"]=d
        if line.startswith("right"):
            d = {}
            for p in line.replace(";"," ").split():
                if p.startswith("x="): d["x"]=float(p[2:])
                if p.startswith("y="): d["y"]=float(p[2:])
                if p.startswith("z="): d["z"]=float(p[2:])
            out["right"]=d
    return out

