            m = re.search(r"Fz=([+-]?[0-9.]+)", r.text)
            if m and abs(float(m.group(1))) > 8:
                print("contact-ish")
                break
        z -= 5
    print("STATUS", workcell.robot("status").text)
    print("FORCE", workcell.robot("force", arm).text)

