import workcell, re

def force():
    t = workcell.robot("force","right").text
    m = re.search(r"Fx=([+-]?[\d.]+) Fy=([+-]?[\d.]+) Fz=([+-]?[\d.]+)", t)
    return float(m.group(1)), float(m.group(2)), float(m.group(3))

def tcp():
    t = workcell.robot("status").text
    line = [l for l in t.splitlines() if l.startswith("right")][0]
    d={}
    for p in line.replace(";"," ").replace("mm","").split():
        if "=" in p and p[0] in "xyz":
            k,v=p.split("=")
            d[k]=float(v)
    return d

def tip():
    t = workcell.call("vision","locate").text
    m = re.search(r"lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; tilt ([-\d.]+)", t)
    if not m:
        return t
    return (float(m.group(1)), float(m.group(2)), float(m.group(3)), float(m.group(4)))

for i in range(25):
    fx,fy,fz = force()
    # comply laterally if side load is high
    if abs(fx)>3 or abs(fy)>3:
        dx = 2 if fx>0 else (-2 if fx<0 else 0)
        dy = 2 if fy>0 else (-2 if fy<0 else 0)
        # only move in the dominant direction, 2mm
        if abs(fx)>=abs(fy):
            dy=0
        else:
            dx=0
        r = workcell.robot("step","right", str(dx), str(dy), "0")
        print(f"comply {dx},{dy}: {r.text.strip()} Fnow {force()}")
    r = workcell.robot("step","right","0","0","-2")
    fx,fy,fz = force()
    p = tcp()
    print(f"down {i}: {r.text.strip()} F {fx:.1f},{fy:.1f},{fz:.1f} z={p['z']:.1f}")
    if "STOPPED" in r.text or abs(fz)>15:
        print("HARD CONTACT")
        break
print("tip", tip())
print(workcell.robot("status").text)
print(workcell.robot("scene").text)
print(workcell.robot("camera","jig").text)
